def transform(ctx):
    src = "발신번호별_호유형_통화요금_합계"
    dst = "할인후합계"

    # A열 기준 마지막 행 찾기
    last = ctx.last_row(src, col=1)
    if last < 2:
        raise ValueError("복사할 데이터가 없습니다.")

    # A2부터 A끝까지 읽기
    data = ctx.read(src, f"A2:A{last}")

    nums = []
    for row in data:
        val = row[0]
        # 숫자 데이터만 필터링
        if isinstance(val, (int, float)):
            nums.append([val])
        elif isinstance(val, str):
            s = val.strip()
            if s:
                try:
                    float(s)
                    nums.append([val])
                except ValueError:
                    pass

    if not nums:
        raise ValueError("숫자 데이터를 찾지 못했습니다.")

    # 할인후합계 시트 A9부터 값으로 쓰기
    ctx.write(dst, "A9", nums, overwrite_formulas=True)

