    # 2. 소스 데이터 읽기 (3행~2000행, A열~G열) 및 딕셔너리 구성
    src_data = ctx.read(src_sheet, "A3:G2000")
    lookup_map = {}
    for row in src_data:
        if row and row[0] is not None:
            key = ctx.normalize(str(row[0]))
            lookup_map[key] = row[src_tgt_idx]

    # 3. 대상 시트 헤더 읽기 및 '타사부가호' 열 인덱스 찾기 (8행 기준)
    dst_hdr = ctx.read(dst_sheet, "A8:K8")[0]
    dst_tgt_idx = None
    for i, h in enumerate(dst_hdr):
        if ctx.normalize(h) == "타사부가호":
            dst_tgt_idx = i
            break
    if dst_tgt_idx is None:
        raise ValueError("대상 시트(할인후합계)에서 '타사부가호' 헤더를 찾을 수 없습니다.")

    # 4. 대상 데이터 읽기 (9행~2000행, A열~K열) 및 값 매칭
    dst_data = ctx.read(dst_sheet, "A9:K2000")
    result = []
    for row in dst_data:
        new_row = list(row)
        if new_row[0] is not None:
            key = ctx.normalize(str(new_row[0]))
            new_row[dst_tgt_idx] = lookup_map.get(key)
        result.append(new_row)

    # 5. 결과 일괄 쓰기
    ctx.write(dst_sheet, "A9", result, overwrite_formulas=True)

