def transform(ctx):
    src_sheet = "발신번호별_호유형_통화요금_합계"
    dst_sheet = "할인후합계"

    # 소스 시트에서 '타사부가호' 열 찾기
    src_headers = ctx.read(src_sheet, "A2:J2")
    src_target_col_idx = None
    for i, h in enumerate(src_headers[0]):
        if ctx.normalize(h) == ctx.normalize("타사부가호"):
            src_target_col_idx = i
            break
    if src_target_col_idx is None:
        raise ValueError("발신번호별_호유형_통화요금_합계 시트에서 '타사부가호' 열을 찾을 수 없습니다.")

    # 소스 데이터 읽기 (A3:J2000)
    src_data = ctx.read(src_sheet, "A3:J2000")
    lookup_dict = {}
    for row in src_data:
        key = row[0]
        if key is not None:
            lookup_dict[ctx.normalize(str(key))] = row[src_target_col_idx]

    # 대상 시트에서 '타사부가호' 열 찾기
    dst_target_col_idx = None
    try:
        dst_target_col_idx = ctx.find_header(dst_sheet, "타사부가호", header_row=8) - 1
    except:
        dst_headers = ctx.read(dst_sheet, "A8:K8")
        for i, h in enumerate(dst_headers[0]):
            if ctx.normalize(h) == ctx.normalize("타사부가호"):
                dst_target_col_idx = i
                break

    if dst_target_col_idx is None:
        raise ValueError("할인후합계 시트에서 '타사부가호' 열을 찾을 수 없습니다.")

    # 대상 데이터 읽기 (A9:K2000)
    dst_data = ctx.read(dst_sheet, "A9:K2000")
    result = []
    for row in dst_data:
        key = row[0]
        if key is not None:
            val = lookup_dict.get(ctx.normalize(str(key)))
            row_copy = list(row)
            row_copy[dst_target_col_idx] = val
            result.append(row_copy)
        else:
            result.append(row)

    # 결과 쓰기
    ctx.write(dst_sheet, "A9", result, overwrite_formulas=True)
